using System.Collections.Immutable;
using DiscordControlCenter.Application.Messaging;
using DiscordControlCenter.Core.Messaging;

namespace DiscordControlCenter.Application.Tests;

public sealed class ScheduledMessageLifecycleServiceTests
{
    [Fact] public async Task EnableIsAtomicAndDoesNotReserveOccurrences() { var repo = new FakeRepo(FakeRepo.Draft()); var service = new ScheduledMessageLifecycleService(repo, new ValidDrafts(), new ScheduledMessageService()); var request = repo.Request(); var result = await service.EnableAsync(request, CancellationToken.None); Assert.True(result.Success); Assert.Equal(ScheduledMessageLifecycle.Enabled, repo.Value!.SavedLifecycle); Assert.Empty(repo.Occurrences); var stale = await service.EnableAsync(request, CancellationToken.None); Assert.True(stale.Conflict || !stale.Success); }
    [Fact] public async Task DisableArchiveAndDeletePreserveOrConservativelyBlockHistory() { var repo = new FakeRepo(FakeRepo.Draft() with { SavedLifecycle = ScheduledMessageLifecycle.Enabled, IsEnabled = true }); var service = new ScheduledMessageLifecycleService(repo, new ValidDrafts(), new ScheduledMessageService()); var disabled = await service.DisableAsync(repo.Request(), CancellationToken.None); Assert.True(disabled.Success); var archived = await service.ArchiveAsync(repo.Request(disabled.NewRevision!.Value), CancellationToken.None); Assert.True(archived.Success); var eligibility = await service.GetDeleteEligibilityAsync(repo.Request(archived.NewRevision!.Value), CancellationToken.None); Assert.False(eligibility.CanDelete); Assert.Equal("Archive preserves retained history safely.", eligibility.SafeAlternative); }
    [Fact] public async Task DraftWithOccurrenceCannotBeDeleted() { var repo = new FakeRepo(FakeRepo.Draft()); repo.Occurrences.Add(new ScheduledMessageOccurrence(Guid.NewGuid(), repo.Value!.Id, DateTimeOffset.UtcNow, MessageOperationState.PendingApproval, Guid.NewGuid(), null, null)); var service = new ScheduledMessageLifecycleService(repo, new ValidDrafts(), new ScheduledMessageService()); var result = await service.DeleteAsync(repo.Request(), CancellationToken.None); Assert.False(result.Success); Assert.Equal("DELETE_BLOCKED", result.FailureCategory); Assert.NotNull(repo.Value); }
    private sealed class ValidDrafts : IScheduledMessageDraftService { public ScheduledMessageDefinition CreateDraft(Guid b, MessageDestination d) => FakeRepo.Draft(); public Task<IReadOnlyList<ScheduledDraftTemplateOption>> GetTemplateOptionsAsync(Guid b, ulong s, CancellationToken c) => Task.FromResult<IReadOnlyList<ScheduledDraftTemplateOption>>([]); public Task<ScheduledMessageDefinition?> LoadAsync(Guid b, ulong s, Guid i, CancellationToken c) => Task.FromResult<ScheduledMessageDefinition?>(null); public Task<ScheduledDraftValidation> ValidateAsync(ScheduledMessageDefinition d, CancellationToken c) => Task.FromResult(new ScheduledDraftValidation([], [], "Daily", [DateTimeOffset.UtcNow.AddDays(1)])); public Task<ScheduledDraftSaveResult> SaveAsync(ScheduledMessageDefinition d, int e, CancellationToken c) => throw new NotSupportedException(); }
    private sealed class FakeRepo(ScheduledMessageDefinition value) : IScheduledMessageRepository { public ScheduledMessageDefinition? Value = value; public List<ScheduledMessageOccurrence> Occurrences { get; } = []; public static ScheduledMessageDefinition Draft() => new(Guid.NewGuid(), Guid.Parse("aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa"), MessageDestination.Channel(1, "Server", 2, "channel"), null, new MessageContent("body", null, AllowedMentionPolicy.None), ScheduledMessageRecurrence.Daily, new TimeOnly(9, 0), "UTC", ImmutableArray<DayOfWeek>.Empty, DateTimeOffset.UtcNow, null, false, MissedOccurrencePolicy.RequireManualApproval, 0, null, null) { Name = "Draft", SavedLifecycle = ScheduledMessageLifecycle.Draft, Revision = 1 }; public ScheduledLifecycleRequest Request(int revision = 1) => new(Value!.BotProfileId, Value.Destination.ServerId, Value.Id, revision); public Task<IReadOnlyList<ScheduledMessageDefinition>> ListEnabledAsync(CancellationToken c) => Task.FromResult<IReadOnlyList<ScheduledMessageDefinition>>(Value?.IsEnabled == true ? [Value] : []); public Task<ScheduledMessageDefinition?> GetScheduleAsync(Guid id, CancellationToken c) => Task.FromResult(Value?.Id == id ? Value : null); public Task<bool> TrySaveAsync(ScheduledMessageDefinition d, int e, CancellationToken c) { if (Value?.Revision != e) return Task.FromResult(false); Value = d; return Task.FromResult(true); } public Task<ScheduledMessageDependencySummary> GetDependencySummaryAsync(Guid i,CancellationToken c) => Task.FromResult(new ScheduledMessageDependencySummary(Occurrences.Count,0,Occurrences.Count(x=>x.State==MessageOperationState.PendingApproval),Occurrences.Count(x=>x.State!=MessageOperationState.PendingApproval))); public Task<bool> TryDeleteAsync(Guid i,int e,CancellationToken c) { if (Value?.Revision != e || Occurrences.Count != 0) return Task.FromResult(false); Value=null; return Task.FromResult(true); } public Task<ScheduledMessagePage> QuerySchedulesAsync(ScheduledMessageQuery q,CancellationToken c)=>throw new NotSupportedException(); public Task<ScheduledMessageFilterOptions> GetScheduleFilterOptionsAsync(Guid b,ulong s,CancellationToken c)=>throw new NotSupportedException(); public Task<IReadOnlyList<ScheduledMessageOccurrenceListItem>> ListRecentOccurrencesAsync(Guid b,ulong s,Guid i,int l,CancellationToken c)=>throw new NotSupportedException(); public Task SaveAsync(ScheduledMessageDefinition d,CancellationToken c)=>throw new NotSupportedException(); public Task<bool> TryReserveOccurrenceAsync(ScheduledMessageOccurrence o,CancellationToken c){Occurrences.Add(o);return Task.FromResult(true);} public Task CompleteOccurrenceAsync(ScheduledMessageOccurrence o,CancellationToken c)=>Task.CompletedTask; public Task<IReadOnlyList<ScheduledMessageApproval>> ListPendingApprovalsAsync(Guid? b,ulong? s,CancellationToken c)=>Task.FromResult<IReadOnlyList<ScheduledMessageApproval>>([]); public Task<ScheduledApprovalPage> QueryApprovalsAsync(ScheduledApprovalQuery q,CancellationToken c)=>throw new NotSupportedException(); public Task<IReadOnlyList<ScheduledApprovalScheduleOption>> ListApprovalSchedulesAsync(Guid? b,ulong? s,CancellationToken c)=>Task.FromResult<IReadOnlyList<ScheduledApprovalScheduleOption>>([]); public Task<ScheduledMessageApproval?> GetApprovalAsync(Guid i,CancellationToken c)=>Task.FromResult<ScheduledMessageApproval?>(null); public Task<bool> TryClaimApprovalAsync(Guid i,Guid x,CancellationToken c)=>Task.FromResult(false); public Task<bool> TryDecideApprovalAsync(Guid i,MessageOperationState s,string d,string? f,CancellationToken c)=>Task.FromResult(false); }
}
